@patch('subprocess.run')
def test_pacman_get_packages(self, mock_run):
    """Test Pacman package listing."""
    def mock_run_side_effect(*args, **kwargs):
        if args[0] == ["pacman", "-Q"]:
            return MagicMock(
                stdout="google-chrome 91.0.4472.77-1\nfirefox 89.0-1\n",
                returncode=0
            )
        elif "pacman" in args[0] and "-Qi" in args[0]:
            if "google-chrome" in args[0]:
                return MagicMock(
                    stdout="Name            : google-chrome\nLicenses        : Proprietary\n",
                    returncode=0
                )
            elif "firefox" in args[0]:
                return MagicMock(
                    stdout="Name            : firefox\nLicenses        : MPL-2.0\n",
                    returncode=0
                )
        return MagicMock(stdout="", returncode=1)

    mock_run.side_effect = mock_run_side_effect

    manager = PacmanManager()
    packages = manager.get_installed_packages()

    self.assertEqual(len(packages), 2)
    self.assertEqual(packages[0]["name"], "google-chrome")
    self.assertEqual(packages[0]["version"], "91.0.4472.77-1")
    self.assertEqual(packages[0]["manager"], "pacman")
    self.assertIn("licenses", packages[0])
